START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261103075901_AddPrivacyRightsAndIncidentManagement') THEN
    CREATE TABLE "PrivacyIncidentLogs" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "IncidentRef" character varying(50) NOT NULL,
        "Title" character varying(200) NOT NULL,
        "DiscoveryTimestamp" timestamp with time zone NOT NULL,
        "CenterNotificationDeadline" timestamp with time zone NOT NULL,
        "Severity" character varying(20) NOT NULL,
        "AffectedDataCategories" character varying(500) NOT NULL,
        "EstimatedAffectedCount" integer NOT NULL,
        "NatureOfBreach" character varying(2000) NOT NULL,
        "LikelyConsequences" character varying(2000) NOT NULL,
        "ContainmentActions" character varying(2000) NOT NULL,
        "RemediationActions" character varying(2000) NOT NULL,
        "NotifiedCenterAt" timestamp with time zone,
        "CenterReferenceNumber" character varying(100),
        "UsersNotifiedAt" timestamp with time zone,
        "Status" character varying(50) NOT NULL,
        "ReportedByAdminId" integer,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_PrivacyIncidentLogs" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_PrivacyIncidentLogs_Users_ReportedByAdminId" FOREIGN KEY ("ReportedByAdminId") REFERENCES "Users" ("Id") ON DELETE SET NULL
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261103075901_AddPrivacyRightsAndIncidentManagement') THEN
    CREATE TABLE "PrivacySubjectRequests" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "UserId" integer NOT NULL,
        "RequestType" character varying(50) NOT NULL,
        "Status" character varying(50) NOT NULL,
        "SubmittedAt" timestamp with time zone NOT NULL,
        "DueDate" timestamp with time zone NOT NULL,
        "VerifiedAt" timestamp with time zone,
        "CompletedAt" timestamp with time zone,
        "RejectionReason" character varying(500),
        "ReviewerNotes" character varying(1000),
        "ProcessorSyncStatus" character varying(100),
        "ExportFormat" character varying(20),
        "ExportToken" character varying(128),
        "ExportExpiresAt" timestamp with time zone,
        "ExportDataJson" text,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_PrivacySubjectRequests" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_PrivacySubjectRequests_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

