        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "PrivacySubjectRequestId" integer NOT NULL,
        "UserId" integer NOT NULL,
        "ProcessorName" character varying(100) NOT NULL,
        "ActionRequested" character varying(100) NOT NULL,
        "Status" character varying(50) NOT NULL,
        "ResponseMessage" character varying(1000),
        "DispatchedAt" timestamp with time zone NOT NULL,
        "AcknowledgedAt" timestamp with time zone,
        CONSTRAINT "PK_ProcessorDeletionLogs" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_ProcessorDeletionLogs_PrivacySubjectRequests_PrivacySubject~" FOREIGN KEY ("PrivacySubjectRequestId") REFERENCES "PrivacySubjectRequests" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

